<?php
namespace App\Controller;

use App\Entity\BankAlertSetting;use App\Entity\BankAnalyticsFavorite;use App\Entity\BankAsset;use App\Entity\BankCategoryRule;use App\Entity\BankSimulation;use App\Entity\BankTransaction;use App\Repository\BankAccountRepository;use App\Repository\BankAlertSettingRepository;use App\Repository\BankAnalyticsFavoriteRepository;use App\Repository\BankAssetRepository;use App\Repository\BankCategoryRepository;use App\Repository\BankCategoryRuleRepository;use App\Repository\BankImportBatchRepository;use App\Repository\BankRecurringRuleRepository;use App\Repository\BankSimulationRepository;use App\Repository\BankTransactionRepository;use App\Repository\BankTransactionSplitRepository;use App\Service\BankAccountManager;use App\Service\BankAlertService;use App\Service\BankImportUndoService;use App\Service\BankNetWorthService;use App\Service\BankReconciliationService;use App\Service\BankSimulationService;use App\Service\BankTransactionSplitManager;use Doctrine\ORM\EntityManagerInterface;use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;use Symfony\Component\HttpFoundation\JsonResponse;use Symfony\Component\HttpFoundation\Request;use Symfony\Component\HttpFoundation\Response;use Symfony\Component\Routing\Attribute\Route;use Symfony\Component\Security\Http\Attribute\IsGranted;

#[Route('/bank',name:'app_bank_')]
#[IsGranted('IS_AUTHENTICATED_REMEMBERED')]
final class BankFeatureController extends AbstractController
{
    #[Route('/transactions/{publicId}/split',name:'transaction_split',methods:['GET','POST'])]
    public function split(string$publicId,Request$request,BankTransactionRepository$transactions,BankTransactionSplitRepository$splits,BankTransactionSplitManager$manager,BankCategoryRepository$categories,EntityManagerInterface$em):Response{$t=$this->transaction($publicId,$transactions);if(in_array($t->getType(),[BankTransaction::TYPE_TRANSFER_IN,BankTransaction::TYPE_TRANSFER_OUT],true))throw$this->createAccessDeniedException('Les virements internes ne peuvent pas être ventilés.');if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_split_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();try{$manager->replace($this->getUser(),$t,(array)$request->request->all('lines'));$em->flush();$this->addFlash('success','Ventilation enregistrée. Les analyses utilisent désormais exclusivement ses lignes.');return$this->redirectToRoute('app_bank_transaction_edit',['publicId'=>$publicId]);}catch(\Throwable$e){$this->addFlash('error',$e->getMessage());}}return$this->render('bank/split.html.twig',['transaction'=>$t,'splits'=>$splits->findForTransaction($t),'splitManager'=>$manager,'categories'=>$categories->findActiveForUser($this->getUser())]);}
    #[Route('/transactions/{publicId}/unsplit',name:'transaction_unsplit',methods:['POST'])]
    public function unsplit(string$publicId,Request$request,BankTransactionRepository$transactions,BankTransactionSplitManager$manager,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_unsplit_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();try{$manager->clear($this->getUser(),$this->transaction($publicId,$transactions));$em->flush();$this->addFlash('success','Ventilation supprimée.');}catch(\Throwable$e){$this->addFlash('error',$e->getMessage());}return$this->redirectToRoute('app_bank_transaction_edit',['publicId'=>$publicId]);}

    #[Route('/category-rules',name:'category_rules',methods:['GET','POST'])]
    public function rules(Request$request,BankCategoryRuleRepository$rules,BankAccountRepository$accounts,BankCategoryRepository$categories,BankAccountManager$accountManager,EntityManagerInterface$em):Response{if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_rule_create',(string)$request->request->get('_token')))throw$this->createAccessDeniedException();try{$category=$categories->findOneForUserByPublicId($this->getUser(),(string)$request->request->get('category'));if(!$category)throw new \InvalidArgumentException('Catégorie invalide.');$account=null;if((string)$request->request->get('account')!==''){$account=$accounts->findOneForUserByPublicId($this->getUser(),(string)$request->request->get('account'));if(!$account)throw new \InvalidArgumentException('Compte invalide.');}$rule=(new BankCategoryRule())->setUser($this->getUser())->setCategory($category)->setAccount($account)->setMatchType((string)$request->request->get('match_type'))->setPattern((string)$request->request->get('pattern'))->setMinimumAmount($request->request->get('minimum_amount'))->setMaximumAmount($request->request->get('maximum_amount'))->setPriority((int)$request->request->get('priority',100));if($rule->getPattern()==='')throw new \InvalidArgumentException('Le motif est obligatoire.');if($rule->getMatchType()===BankCategoryRule::MATCH_REGEX&&@preg_match($rule->getPattern(),'')===false)throw new \InvalidArgumentException('Expression régulière invalide.');$em->persist($rule);$em->flush();$this->addFlash('success','Règle enregistrée.');return$this->redirectToRoute('app_bank_category_rules');}catch(\Throwable$e){$this->addFlash('error',$e->getMessage());}}return$this->render('bank/category_rules.html.twig',['rules'=>$rules->findAllForUser($this->getUser()),'accounts'=>$accounts->findActiveForUser($this->getUser()),'categories'=>$categories->findActiveForUser($this->getUser()),'accountManager'=>$accountManager]);}
    #[Route('/category-rules/{publicId}/archive',name:'category_rule_archive',methods:['POST'])]
    public function ruleArchive(string$publicId,Request$request,BankCategoryRuleRepository$rules,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_rule_archive_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$rule=$rules->findOneForUser($this->getUser(),$publicId);if(!$rule)throw$this->createNotFoundException();$rule->archive();$em->flush();return$this->redirectToRoute('app_bank_category_rules');}

    #[Route('/simulations',name:'simulations',methods:['GET','POST'])]
    public function simulations(Request$request,BankSimulationRepository$repository,BankSimulationService$service,EntityManagerInterface$em):Response{$horizon=(string)$request->request->get('horizon',$request->query->get('horizon','month_end'));$assumptions=(array)$request->request->all('assumptions');$result=null;if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_simulation',(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$result=$service->calculate($this->getUser(),$horizon,$assumptions);if($request->request->getBoolean('save')){$name=trim((string)$request->request->get('name'));if($name===''){$this->addFlash('error','Un nom est requis pour enregistrer la simulation.');}else{$simulation=(new BankSimulation())->setUser($this->getUser())->setName($name)->setHorizon($horizon)->setAssumptions($assumptions);$em->persist($simulation);$em->flush();$this->addFlash('success','Simulation enregistrée.');}}}elseif(($id=(string)$request->query->get('load'))!==''){$simulation=$repository->findOneForUser($this->getUser(),$id);if($simulation){$horizon=$simulation->getHorizon();$assumptions=$simulation->getAssumptions();$result=$service->fromEntity($this->getUser(),$simulation);}}return$this->render('bank/simulations.html.twig',['horizons'=>BankSimulationService::horizons(),'horizon'=>$horizon,'assumptions'=>$assumptions,'result'=>$result,'saved'=>$repository->findActiveForUser($this->getUser())]);}
    #[Route('/simulations/{publicId}/archive',name:'simulation_archive',methods:['POST'])]
    public function simulationArchive(string$publicId,Request$request,BankSimulationRepository$repo,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_simulation_archive_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$s=$repo->findOneForUser($this->getUser(),$publicId);if(!$s)throw$this->createNotFoundException();$s->archive();$em->flush();return$this->redirectToRoute('app_bank_simulations');}

    #[Route('/net-worth',name:'net_worth',methods:['GET','POST'])]
    public function netWorth(Request$request,BankAssetRepository$assets,BankNetWorthService$service,EntityManagerInterface$em):Response{if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_asset_save',(string)$request->request->get('_token')))throw$this->createAccessDeniedException();try{$id=(string)$request->request->get('asset');$asset=$id!==''?$assets->findOneForUser($this->getUser(),$id):new BankAsset();if(!$asset)throw new \InvalidArgumentException('Élément patrimonial invalide.');$asset->setUser($this->getUser())->setName((string)$request->request->get('name'))->setType((string)$request->request->get('type'));if($asset->getName()==='')throw new \InvalidArgumentException('Le nom est obligatoire.');$em->persist($asset);$service->record($asset,(float)str_replace(',','.',(string)$request->request->get('value')),new \DateTime((string)$request->request->get('date','today')));$em->flush();$this->addFlash('success','Valeur patrimoniale enregistrée.');return$this->redirectToRoute('app_bank_net_worth');}catch(\Throwable$e){$this->addFlash('error',$e->getMessage());}}$rows=$assets->findActiveForUser($this->getUser());return$this->render('bank/net_worth.html.twig',['assets'=>$rows,'snapshot'=>$service->snapshot($this->getUser()),'history'=>$service->history($rows)]);}
    #[Route('/net-worth/{publicId}/archive',name:'asset_archive',methods:['POST'])]
    public function assetArchive(string$publicId,Request$request,BankAssetRepository$assets,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_asset_archive_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$a=$assets->findOneForUser($this->getUser(),$publicId);if(!$a)throw$this->createNotFoundException();$a->archive();$em->flush();return$this->redirectToRoute('app_bank_net_worth');}

    #[Route('/alerts',name:'alerts',methods:['GET','POST'])]
    public function alerts(Request$request,BankAlertSettingRepository$settings,BankAlertService$service,BankAccountRepository$accounts,\App\Repository\BankBudgetRepository$budgets,BankRecurringRuleRepository$rules,BankAccountManager$accountManager,EntityManagerInterface$em):Response{$service->ensureDefaults($this->getUser());if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_alert_save',(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$id=(string)$request->request->get('setting');$setting=$id!==''?$settings->findOneForUser($this->getUser(),$id):new BankAlertSetting();if(!$setting)throw$this->createNotFoundException();$setting->setUser($this->getUser())->setType((string)$request->request->get('type'))->setTargetType((string)$request->request->get('target_type'))->setTargetPublicId($request->request->get('target_public_id'))->setThreshold($request->request->get('threshold'))->setActive($request->request->getBoolean('active'));$em->persist($setting);$em->flush();$this->addFlash('success','Alerte enregistrée.');return$this->redirectToRoute('app_bank_alerts');}$em->flush();return$this->render('bank/alerts.html.twig',['settings'=>$settings->findAllForUser($this->getUser()),'accounts'=>$accounts->findActiveForUser($this->getUser()),'budgets'=>$budgets->findActiveForUser($this->getUser()),'rules'=>$rules->findActiveForUser($this->getUser()),'accountManager'=>$accountManager]);}

    #[Route('/reconciliation',name:'reconciliation',methods:['GET','POST'])]
    public function reconciliation(Request$request,BankAccountRepository$accounts,BankAccountManager$accountManager,BankReconciliationService$service,EntityManagerInterface$em):Response{$inspection=null;$candidates=null;$account=null;$session=$request->getSession();if($request->isMethod('POST')){if(!$this->isCsrfTokenValid('bank_reconciliation',(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$account=$accounts->findOneForUserByPublicId($this->getUser(),(string)$request->request->get('account'));if(!$account)throw$this->createNotFoundException('Compte invalide.');$phase=(string)$request->request->get('phase','upload');if($phase==='upload'){$file=$request->files->get('statement');if(!$file||($file->getSize()??0)>5*1024*1024){$this->addFlash('error','Sélectionnez un relevé CSV de 5 Mo maximum.');}else{$content=(string)file_get_contents($file->getPathname());$inspection=$service->inspect($content);$session->set('bank_reconciliation',['content'=>$content,'filename'=>$file->getClientOriginalName(),'account'=>$account->getPublicId()]);}}elseif($phase==='map'){$stored=(array)$session->get('bank_reconciliation',[]);if(($stored['account']??null)!==$account->getPublicId())throw new \RuntimeException('Session de rapprochement invalide.');$inspection=$service->inspect((string)$stored['content']);$mapping=['date'=>(string)$request->request->get('date_column'),'amount'=>(string)$request->request->get('amount_column'),'label'=>(string)$request->request->get('label_column')];$candidates=$service->candidates($this->getUser(),$account,$inspection['rows'],$mapping,(string)$request->request->get('date_format','d/m/Y'));$session->set('bank_reconciliation_candidates',array_map(static fn($row)=>['transaction'=>$row['transaction']?->getPublicId(),'date'=>$row['date'],'amount'=>$row['amount'],'label'=>$row['label']],$candidates));}elseif($phase==='confirm'){$stored=(array)$session->get('bank_reconciliation',[]);$candidateRows=(array)$session->get('bank_reconciliation_candidates',[]);$allowed=array_filter(array_column($candidateRows,'transaction'));$selected=array_values(array_intersect($allowed,(array)$request->request->all('transactions')));$toCreate=[];foreach(array_map('intval',(array)$request->request->all('create_rows'))as$idx){if(isset($candidateRows[$idx])&&$candidateRows[$idx]['transaction']===null)$toCreate[]=$candidateRows[$idx];}$batch=$service->confirm($this->getUser(),$account,(string)($stored['filename']??'releve.csv'),$selected,$toCreate);$em->flush();$session->remove('bank_reconciliation');$session->remove('bank_reconciliation_candidates');$this->addFlash('success',sprintf('%d opération(s) rapprochée(s) après validation.',$batch->getMatchedCount()));return$this->redirectToRoute('app_bank_reconciliation');}}return$this->render('bank/reconciliation.html.twig',['accounts'=>$accounts->findActiveForUser($this->getUser()),'accountManager'=>$accountManager,'selectedAccount'=>$account,'inspection'=>$inspection,'candidates'=>$candidates]);}

    #[Route('/imports/{publicId}/undo',name:'import_undo',methods:['POST'])]
    public function importUndo(string$publicId,Request$request,BankImportBatchRepository$batches,BankImportUndoService$undo,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_import_undo_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$batch=$batches->findOneForUser($this->getUser(),$publicId);if(!$batch||$batch->isUndone())throw$this->createNotFoundException();$result=$undo->undo($this->getUser(),$batch);$em->flush();$this->addFlash('warning',sprintf('%d opération(s) intacte(s) archivée(s) ; %d opération(s) modifiée(s), ventilée(s), vérifiée(s) ou rapprochée(s) conservée(s).',$result['archived'],$result['protected']));return$this->redirectToRoute('app_bank_import');}

    #[Route('/analytics/favorites',name:'analytics_favorite',methods:['POST'])]
    public function favorite(Request$request,BankAnalyticsFavoriteRepository$favorites,EntityManagerInterface$em):JsonResponse{if(!$this->isCsrfTokenValid('bank_analytics_favorite',(string)$request->request->get('_token')))return$this->json(['error'=>'Token CSRF invalide.'],403);$name=trim((string)$request->request->get('name'));if($name==='')return$this->json(['error'=>'Le nom est obligatoire.'],400);$filters=json_decode((string)$request->request->get('filters_json','{}'),true);$favorite=(new BankAnalyticsFavorite())->setUser($this->getUser())->setName($name)->setFilters(is_array($filters)?$filters:[]);$em->persist($favorite);$em->flush();return$this->json(['id'=>$favorite->getPublicId(),'name'=>$favorite->getName()],201);}

    #[Route('/analytics/favorites/{publicId}/delete',name:'analytics_favorite_delete',methods:['POST'])]
    public function favoriteDelete(string$publicId,Request$request,BankAnalyticsFavoriteRepository$favorites,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_analytics_favorite_delete_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$favorite=$favorites->findOneForUser($this->getUser(),$publicId);if(!$favorite)throw$this->createNotFoundException();$em->remove($favorite);$em->flush();return$this->redirectToRoute('app_bank_analytics');}

    #[Route('/attachments/{publicId}/archive',name:'attachment_archive',methods:['POST'])]
    public function attachmentArchive(string$publicId,Request$request,\App\Repository\BankAttachmentRepository$attachments,\App\Service\BankAttachmentManager$manager,EntityManagerInterface$em):Response{if(!$this->isCsrfTokenValid('bank_attachment_archive_'.$publicId,(string)$request->request->get('_token')))throw$this->createAccessDeniedException();$attachment=$attachments->findOneForUserByPublicId($this->getUser(),$publicId);if(!$attachment||$attachment->isArchived())throw$this->createNotFoundException();$transactionId=$attachment->getTransaction()?->getPublicId();$manager->archive($this->getUser(),$attachment);$em->flush();return$this->redirectToRoute('app_bank_transaction_edit',['publicId'=>$transactionId]);}

    private function transaction(string$id,BankTransactionRepository$repo):BankTransaction{$t=$repo->findOneForUserByPublicId($this->getUser(),$id);if(!$t||$t->isArchived())throw$this->createNotFoundException();return$t;}
}
